/*
 * Browser half of @soffits/dsh-web-tweaks. Generated by scripts/build-client.js from each feature's
 * client.js and src/runtime.js: edit those, then run `npm run build`.
 */
window.__ModuleLoader__.load({
  id: "@soffits/dsh-web-tweaks",
  factory(require) {
    const factories = new Map()
    const feature = (key, { factory }) => { factories.set(key, factory) }

// ---- features/custom-css/client.js
/*
 * Browser half of dsh-custom-css: links the stylesheet the Host plugin serves
 * into the page head. A <link> is plain CSS, so it keeps working while the
 * connection to DSH is down or coming back. The plugin's settings reach this
 * module as custom properties in that stylesheet, and it acts on them: the
 * tags that ask a phone for the whole screen (`edgeToEdge`), readings of what
 * the browser reports sent to the Host (`report`) or drawn over the page
 * (`probe`), and the recovery experiment (`recover`). When the page comes back
 * to the front it asks the Host whether its stylesheet is still the current
 * one, so a changed setting needs no reload. A request to the Host that fails
 * is counted, and the next report that arrives says so.
 * Plain JavaScript in DSH's Client module format (no build step).
 */
feature("customCss", {
  id: 'dsh-custom-css',
  factory: function self() {
    const LINK_ID = 'dsh-custom-css'
    const PROBE_ID = 'dsh-custom-css-probe'
    const SETTING = '--dsh-custom-css-'
    const RELOADED_KEY = 'dsh-custom-css-reloaded'
    const UNSENT_KEY = 'dsh-custom-css-unsent'
    /** The response header in which the Host names its current stylesheet. An `etag` would say the same, but proxies rewrite those. */
    const REVISION_HEADER = 'x-custom-css-revision'
    const SIDES = ['Top', 'Right', 'Bottom', 'Left']
    const DISPLAY_MODES = ['standalone', 'fullscreen', 'minimal-ui', 'browser']
    /** How long a tap mark stays on the page, in ms. */
    const MARK_MS = 4000
    /** A burst of events (a rotation fires several) is over after this much quiet, in ms. */
    const QUIET_MS = 400
    /** iOS can finish laying a page out well after its last event: one more look this long after the quiet, in ms. */
    const LATE_MS = 2500
    /** How long a recovery try gets before its result is read, in ms. */
    const TRY_MS = 700
    /** Taps are reported for this long after a burst, in ms, and at most this many of them. */
    const TAP_MS = 30000
    const TAP_COUNT = 20
    /** A page out of step with its Host half asks again when it is touched, at most this often, in ms. */
    const TOUCH_ASK_MS = 5000
    /** Events after which the sizes may have changed, by what they are fired on. */
    const EVENTS = {
      window: ['resize', 'orientationchange', 'pageshow', 'pagehide', 'scroll'],
      document: ['visibilitychange'],
      viewport: ['resize', 'scroll'],
    }

    /** FNV-1a over UTF-16 code units, as 8 hex digits; the Host names this module's text the same way. */
    function fnv1a(text) {
      let hash = 0x811c9dc5
      for (let i = 0; i < text.length; i += 1) hash = Math.imul(hash ^ text.charCodeAt(i), 0x01000193)
      return (hash >>> 0).toString(16).padStart(8, '0')
    }
    /** Which build of this module the page is running. */
    const BUILD = fnv1a(self.toString())

    /**
     * What a page declares to get the whole screen as an iOS home-screen app: the viewport reaching under
     * the unsafe areas, and the status bar drawn over the page instead of above it. iOS reads the last two
     * when the icon is added to the home screen, so they have to be in the document by then.
     */
    const EDGE_META = [
      ['viewport', content => [...content.split(',').map(part => part.trim()).filter(part => part !== '' && !part.startsWith('viewport-fit')), 'viewport-fit=cover'].join(', ')],
      ['apple-mobile-web-app-capable', () => 'yes'],
      ['apple-mobile-web-app-status-bar-style', () => 'black-translucent'],
    ]

    /**
     * The tries of the `recover` setting, for an iOS home-screen app that kept the other orientation's inset
     * after a rotation: the window has its new size, but the page is still laid out short by the old inset
     * and scrolled to a negative offset, which leaves an empty band. The first four may make iOS lay the
     * page out again; `cover` gives up on that and puts DSH's box over what is visible instead, for as
     * long as the state lasts. None is known to work, which is what the reports are for.
     * A try may return a function that undoes it.
     */
    const RECOVERIES = {
      /** Change the viewport tag and put it back, so the browser works its viewport out again. */
      meta(doc) {
        const meta = doc.querySelector('meta[name="viewport"]')
        if (meta === null) return
        const content = meta.content
        meta.content = content.includes('viewport-fit=cover') ? content.replace('viewport-fit=cover', 'viewport-fit=auto') : `${content}, viewport-fit=cover`
        doc.defaultView.setTimeout(() => { meta.content = content }, 50)
      },
      /** Change the root's height and force a layout with it. */
      style(doc) {
        const root = doc.documentElement
        const height = root.style.height
        root.style.height = 'calc(100% + 1px)'
        void root.offsetHeight
        root.style.height = height
      },
      /** Scroll the window and back. */
      scroll(doc) {
        doc.defaultView.scrollTo(0, 1)
        doc.defaultView.scrollTo(0, 0)
      },
      /** Load the page again; DSH comes back where it was. */
      reload(doc) {
        doc.defaultView.location.reload()
      },
      /** Give body the visual viewport's box in the document. Kept in place by the watch, which calls it again after every event. */
      cover(doc) {
        const { body, defaultView: { visualViewport: vv } } = doc
        const placed = { 'margin-top': `${vv.pageTop}px`, 'margin-left': `${vv.pageLeft}px`, width: `${vv.width}px`, height: `${vv.height}px` }
        const before = Object.keys(placed).map(name => [name, body.style.getPropertyValue(name)])
        for (const [name, value] of Object.entries(placed)) body.style.setProperty(name, value)
        return () => { for (const [name, value] of before) body.style.setProperty(name, value) }
      },
    }

    const round = (value) => Math.round(value * 10) / 10
    const rect = (el) => {
      const r = el.getBoundingClientRect()
      return [r.x, r.y, r.width, r.height].map(round)
    }
    const box = ([x, y, width, height]) => `${x},${y} ${width}×${height}`

    /** Calls `handler` for every event in EVENTS. @returns {() => void} Stops it. */
    function listen(doc, handler) {
      const targets = { window: doc.defaultView, document: doc, viewport: doc.defaultView.visualViewport }
      const each = (method) => {
        for (const [where, types] of Object.entries(EVENTS)) for (const type of types) targets[where]?.[method](type, handler, { passive: true })
      }
      each('addEventListener')
      return () => each('removeEventListener')
    }

    /** The plugin's settings as the loaded stylesheet carries them. */
    function readSettings(doc) {
      const root = doc.defaultView.getComputedStyle(doc.documentElement)
      const value = (name) => root.getPropertyValue(SETTING + name).trim().replace(/^"|"$/g, '')
      return {
        edge: value('edge') === '1',
        probe: value('probe') === '1',
        report: value('report') === '1',
        recover: value('recover').split(/\s+/).filter(name => Object.hasOwn(RECOVERIES, name)),
        build: value('build'),
        revision: value('revision'),
      }
    }

    /**
     * Sets the edge-to-edge tags, changing a tag the page already has and adding one it lacks.
     * @returns {() => void} Puts the head back as it was.
     */
    function claimScreen(doc) {
      const undo = EDGE_META.map(([name, next]) => {
        const existing = doc.querySelector(`meta[name="${name}"]`)
        if (existing === null) {
          const meta = doc.createElement('meta')
          meta.name = name
          meta.content = next('')
          doc.head.appendChild(meta)
          return () => meta.remove()
        }
        const before = existing.content
        existing.content = next(before)
        return () => { existing.content = before }
      })
      return () => { for (const restore of undo) restore() }
    }

    /**
     * Counts the requests to the Host that failed (a report, the stylesheet, the question about its revision)
     * and the features that would not start, with the time of the first and what the last one was, until a
     * report gets through and takes the count along. Kept in `localStorage`, because what follows a failure
     * is often a new page: a sign-in, a reload, the app started again. Storage can be refused (private
     * browsing); then the count lasts as long as the page.
     * @returns {{ note: (what: string, error: unknown, line?: object) => void, pending: () => object | null, sent: (count: number) => void, clear: () => void }}
     */
    function createTally(win) {
      let held = null
      try { held = JSON.parse(win.localStorage.getItem(UNSENT_KEY)) } catch { /* refused or unreadable: start empty */ }
      const keep = (value) => {
        held = value
        try { if (value === null) win.localStorage.removeItem(UNSENT_KEY); else win.localStorage.setItem(UNSENT_KEY, JSON.stringify(value)) } catch { /* nothing to keep it in */ }
      }
      return {
        note(what, error, line) {
          const t = new Date().toISOString()
          keep({ count: (held?.count ?? 0) + 1, since: held?.since ?? t, last: { t, what, error: String(error?.message ?? error), ...(line ? { line } : {}) } })
        },
        pending: () => held,
        /** A report that carried the first `count` failures arrived; later ones stay. */
        sent(count) { keep(held !== null && held.count > count ? { ...held, count: held.count - count } : null) },
        clear() { keep(null) },
      }
    }

    /**
     * Reads what the browser reports about the page. The safe-area insets are measured on a padded element.
     * `stale` is the state the recovery experiment looks for: the page is scrolled to a negative offset, or
     * a home-screen app is laid out smaller than its window. (`screen` is no help: a folding phone can
     * report its other display.) `popups` are DSH's script-placed popups that are open, with where their
     * inline style puts them and where they are.
     * @returns {{ read: () => object, stop: () => void }}
     */
    function createReader(doc) {
      const win = doc.defaultView
      const meter = doc.createElement('div')
      meter.style.cssText = 'position:absolute;visibility:hidden;pointer-events:none;padding:env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left)'
      doc.body.append(meter)
      return {
        read() {
          const vv = win.visualViewport
          const root = doc.getElementById('root')
          const padding = win.getComputedStyle(meter)
          const display = DISPLAY_MODES.find(mode => win.matchMedia(`(display-mode: ${mode})`).matches) ?? null
          const standalone = win.navigator.standalone ?? null
          const html = doc.documentElement
          const shifted = win.scrollX < 0 || win.scrollY < 0 || (vv ? vv.pageLeft < 0 || vv.pageTop < 0 : false)
          const short = html.clientWidth < win.innerWidth - 1 || html.clientHeight < win.innerHeight - 1
          return {
            window: [win.innerWidth, win.innerHeight],
            html: [html.clientWidth, html.clientHeight],
            dpr: win.devicePixelRatio,
            visual: vv ? { size: [vv.width, vv.height].map(round), offset: [vv.offsetLeft, vv.offsetTop].map(round), page: [vv.pageLeft, vv.pageTop].map(round), scale: round(vv.scale) } : null,
            screen: { size: [win.screen.width, win.screen.height], orientation: win.screen.orientation?.type ?? null, angle: win.screen.orientation?.angle ?? null },
            insets: SIDES.map(side => round(parseFloat(padding[`padding${side}`]) || 0)),
            body: rect(doc.body),
            root: root ? rect(root) : null,
            scroll: [win.scrollX, win.scrollY],
            standalone,
            display,
            visibility: doc.visibilityState,
            meta: Object.fromEntries(EDGE_META.map(([name]) => [name, doc.querySelector(`meta[name="${name}"]`)?.content ?? null])),
            popups: [...doc.querySelectorAll('body > [style*="top:"][style*="left:"]')].slice(0, 3).map(el => ({ inline: [el.style.left, el.style.top], rect: rect(el) })),
            stale: shifted || ((standalone === true || display === 'standalone') && short),
          }
        },
        stop: () => meter.remove(),
      }
    }

    /** Counts animation frames while it runs. `rate()` is frames per second since it started or was last asked. */
    function frameMeter(win) {
      let frames = 0
      let since = 0
      let frame = null
      const tick = () => { frames += 1; frame = win.requestAnimationFrame(tick) }
      return {
        start() {
          if (frame !== null) return
          frames = 0
          since = win.performance.now()
          frame = win.requestAnimationFrame(tick)
        },
        rate() {
          const elapsed = win.performance.now() - since
          const rate = frame === null || elapsed < 100 ? null : Math.round(frames * 1000 / elapsed)
          frames = 0
          since = win.performance.now()
          return rate
        },
        stop() {
          if (frame !== null) win.cancelAnimationFrame(frame)
          frame = null
        },
      }
    }

    /** What a tap hit, named the way a person would find it on screen. Without `text`, by its label only: reports carry no page content. */
    function describe(target, { text = true } = {}) {
      const el = target?.nodeType === 1 ? target : null
      const named = el?.closest('[aria-label]')
      const label = named?.getAttribute('aria-label') ?? (text ? el?.textContent?.trim().slice(0, 24) : undefined) ?? ''
      return `${el?.tagName.toLowerCase() ?? '?'}${label ? ` "${label}"` : ''}${el ? ` @${box(rect(named ?? el))}` : ''}`
    }

    /**
     * The probe panel: the readings and a mark where each tap lands, drawn in the document (not in a fixed
     * layer), so a mark away from the finger shows that drawing and hit-testing disagree.
     * Marks are placed from body's own box, wherever the page puts it, and with `inset`: the edge-to-edge
     * rule moves children of body that carry an inline `top` and `left`, which is how it recognises DSH's popups.
     * @returns {() => void} Removes everything it added.
     */
    function startPanel(doc, reader) {
      const win = doc.defaultView
      const panel = doc.createElement('pre')
      panel.id = PROBE_ID
      panel.style.cssText = 'position:absolute;z-index:2147483647;inset:40% auto auto 50%;transform:translateX(-50%);margin:0;padding:6px 8px;max-width:90vw;white-space:pre-wrap;font:11px/1.35 ui-monospace,monospace;color:#fff;background:rgba(0,0,0,.78);border:1px solid #f0f;border-radius:6px;pointer-events:none'
      doc.body.append(panel)
      const marks = new Set()
      const log = []
      const frames = frameMeter(win)
      let lastTap = ''
      let fps = 0
      frames.start()

      const render = () => {
        const r = reader.read()
        const size = ([width, height]) => `${width}×${height}`
        panel.textContent = [
          `window ${size(r.window)}  html ${size(r.html)}  dpr ${r.dpr}`,
          r.visual ? `visual ${size(r.visual.size)} offset ${r.visual.offset} page ${r.visual.page} scale ${r.visual.scale}` : 'visual (none)',
          `screen ${size(r.screen.size)} ${r.screen.orientation ?? ''} ${r.screen.angle ?? ''}`,
          `scroll ${r.scroll}  safe-area t r b l ${r.insets.join(' ')}`,
          `body ${box(r.body)}  root ${r.root ? box(r.root) : '-'}`,
          `standalone ${r.standalone ?? '-'} display ${r.display ?? '-'}  ${r.visibility}  frames/s ${fps}${r.stale ? '  STALE' : ''}`,
          `tap ${lastTap}`,
          ...log,
        ].join('\n')
      }
      const note = (event) => {
        log.unshift(`${new Date().toISOString().slice(11, 23)} ${event.type} ${win.innerWidth}×${win.innerHeight}`)
        log.length = Math.min(log.length, 4)
        render()
      }
      const onTap = (event) => {
        const mark = doc.createElement('div')
        const origin = doc.body.getBoundingClientRect()
        mark.style.cssText = `position:absolute;z-index:2147483647;inset:${event.clientY - origin.y - 12}px auto auto ${event.clientX - origin.x - 12}px;width:22px;height:22px;border:2px solid #f0f;border-radius:50%;pointer-events:none`
        doc.body.append(mark)
        marks.add(mark)
        win.setTimeout(() => { mark.remove(); marks.delete(mark) }, MARK_MS)
        lastTap = `${round(event.clientX)},${round(event.clientY)} → ${describe(event.target)}`
        render()
      }
      const second = win.setInterval(() => { fps = frames.rate() ?? 0; render() }, 1000)
      const unlisten = listen(doc, note)
      doc.addEventListener('pointerdown', onTap, { capture: true, passive: true })
      render()

      return () => {
        frames.stop()
        win.clearInterval(second)
        unlisten()
        doc.removeEventListener('pointerdown', onTap, { capture: true })
        for (const mark of marks) mark.remove()
        panel.remove()
      }
    }

    /**
     * Follows the page's size events. A burst (a rotation fires several) gives a reading at its first
     * event, one when it has gone quiet (`settled`) and one later if anything still moved (`late`).
     * With `report` on each reading is sent to the Host, and so is every tap for a while after a burst or
     * while the page is stale (where the finger was, and what it hit). With `recover` set, a settled
     * reading that is stale starts the tries, each sent before and after. A report the Host did not take
     * (no answer, or not its answer) goes into the tally, and the next one that arrives carries the tally
     * as `unsent`.
     * @param {object} options
     * @param {string} options.url - Where reports go.
     * @param {object} options.settings
     * @param {{ read: () => object }} options.reader
     * @param {{ id: string, seq: number }} options.page - The document's name in its reports and the number of its last one; both outlive a change of settings.
     * @param {ReturnType<typeof createTally>} options.tally
     * @param {(revision: string) => void} options.onRevision - Told the Host's current revision with every answer.
     * @returns {() => void} Stops it.
     */
    function startWatch(doc, { url, settings, reader, page, tally, onRevision }) {
      const win = doc.defaultView
      const frames = frameMeter(win)
      const timers = new Set()
      const after = (ms, fn) => {
        const timer = win.setTimeout(() => { timers.delete(timer); fn() }, ms)
        timers.add(timer)
        return timer
      }
      const cancel = (timer) => { win.clearTimeout(timer); timers.delete(timer) }
      /** Window sizes at which a full round of tries cleared nothing; not tried again. */
      const gaveUp = new Set()
      let burst = null
      let settledAs = ''
      let trying = false
      let undoTry = null
      let tapsUntil = 0
      let tapsLeft = 0
      /** Remembers a reload across it. Storage can be refused (private browsing); then a reload is simply never tried twice in a row from one page. */
      const memory = {
        get: () => { try { return win.sessionStorage.getItem(RELOADED_KEY) === '1' } catch { return false } },
        set: (on) => { try { if (on) win.sessionStorage.setItem(RELOADED_KEY, '1'); else win.sessionStorage.removeItem(RELOADED_KEY) } catch { /* nothing to remember with */ } },
      }
      let reloaded = memory.get()

      /** `keepalive` lets a line outlive its page, and browsers ration it, so only a page on its way out asks for it. */
      const send = (line) => {
        const unsent = tally.pending()
        win.fetch(url, { method: 'POST', keepalive: doc.visibilityState === 'hidden', headers: { 'content-type': 'application/json' }, body: JSON.stringify(unsent ? { ...line, unsent } : line) })
          .then(async (response) => {
            if (!response.ok) throw new Error(`HTTP ${response.status}`)
            const answer = await response.json()
            if (unsent) tally.sent(unsent.count)
            onRevision(answer.revision)
          })
          .catch(error => tally.note('report', error, line))
      }
      const look = (event, extra = {}) => {
        const reading = reader.read()
        if (!reading.stale && reloaded) {
          reloaded = false
          memory.set(false)
        }
        if (settings.report) {
          page.seq += 1
          const line = { seq: page.seq, page: page.id, t: new Date().toISOString(), ms: Math.round(win.performance.now()), event, ...extra, ...reading, fps: frames.rate(), settings: { edge: settings.edge, probe: settings.probe, recover: settings.recover }, revision: settings.revision, build: settings.build, client: BUILD, ua: win.navigator.userAgent }
          send(line)
        }
        return reading
      }

      const recover = async (size) => {
        trying = true
        for (const name of settings.recover) {
          if (name === 'reload' && reloaded) continue
          look(`before:${name}`)
          if (name === 'reload') {
            reloaded = true
            memory.set(true)
          }
          const undo = RECOVERIES[name](doc)
          await new Promise((resolve) => { after(TRY_MS, resolve) })
          const cleared = !look(`after:${name}`).stale
          if (undo) undoTry = { name, undo }
          if (cleared || undo) {
            trying = false
            return
          }
        }
        gaveUp.add(size)
        trying = false
      }
      /** A try that stays in place follows the page while it is stale and goes when it no longer is. */
      const follow = (stale) => {
        if (undoTry === null || trying) return
        undoTry.undo()
        if (stale) {
          undoTry.undo = RECOVERIES[undoTry.name](doc)
        } else {
          look(`dropped:${undoTry.name}`)
          undoTry = null
        }
      }
      const onTap = (event) => {
        const stale = reader.read().stale
        if (!settings.report || tapsLeft <= 0 || (!stale && win.performance.now() > tapsUntil)) return
        tapsLeft -= 1
        const at = doc.elementFromPoint(event.clientX, event.clientY)
        const hit = event.target?.nodeType === 1 ? event.target.getBoundingClientRect() : null
        look('tap', { tap: {
          client: [event.clientX, event.clientY].map(round),
          page: [event.pageX, event.pageY].map(round),
          target: describe(event.target, { text: false }),
          inside: hit !== null && event.clientX >= hit.left && event.clientX <= hit.right && event.clientY >= hit.top && event.clientY <= hit.bottom,
          drawnThere: describe(at, { text: false }),
        } })
      }

      const settle = () => {
        const events = burst.events
        burst.quiet = null
        burst.settled = true
        follow(reader.read().stale)
        const reading = look('settled', { events })
        settledAs = JSON.stringify(reading)
        tapsUntil = win.performance.now() + TAP_MS
        tapsLeft = TAP_COUNT
        const size = reading.window.join('x')
        if (reading.stale && settings.recover.length > 0 && !trying && undoTry === null && !gaveUp.has(size)) recover(size)
        burst.late = after(LATE_MS, () => {
          burst = null
          const now = reader.read()
          if (JSON.stringify(now) !== settledAs) look('late')
          frames.stop()
        })
      }
      const onEvent = (event) => {
        if (burst === null || burst.settled) {
          if (burst !== null) cancel(burst.late)
          burst = { events: [], quiet: null, late: null, settled: false }
          frames.start()
          follow(look(event.type).stale)
        } else {
          cancel(burst.quiet)
        }
        burst.events.push(event.type)
        burst.quiet = after(QUIET_MS, settle)
      }

      const unlisten = listen(doc, onEvent)
      doc.addEventListener('pointerdown', onTap, { capture: true, passive: true })
      // the document's first line is its load; a later start is new settings arriving
      onEvent({ type: reloaded ? 'after:reload' : page.seq === 0 ? 'load' : 'settings' })
      return () => {
        unlisten()
        doc.removeEventListener('pointerdown', onTap, { capture: true })
        frames.stop()
        for (const timer of timers) win.clearTimeout(timer)
        undoTry?.undo()
      }
    }

    /**
     * Starts what the settings ask for.
     * @param {{ page: { id: string, seq: number }, tally: ReturnType<typeof createTally>, onRevision: (revision: string) => void }} shared - What outlives a change of settings.
     * @returns {() => void} Stops all of it.
     */
    function startFeatures(doc, settings, shared) {
      const stops = []
      const stop = () => { for (const each of stops.splice(0).reverse()) each() }
      try {
        if (settings.edge) stops.push(claimScreen(doc))
        // this Host half's stylesheet says nothing will be sent, so nothing is kept to send
        if (settings.build !== '' && !settings.report) shared.tally.clear()
        const watching = settings.report || settings.recover.length > 0
        if (settings.probe || watching) {
          const reader = createReader(doc)
          stops.push(reader.stop)
          if (settings.probe && doc.getElementById(PROBE_ID) === null) stops.push(startPanel(doc, reader))
          if (watching) stops.push(startWatch(doc, { url: new URL('custom-css/report', doc.baseURI).href, settings, reader, ...shared }))
        }
      } catch (error) {
        stop()
        throw error
      }
      return stop
    }

    /**
     * Links the stylesheet and runs what its settings ask for. The features follow what the stylesheet in
     * the page says, read when one finishes loading and again whenever the page is shown or touched, so
     * they start even where a load event went missing. When the page comes to the front it asks the Host
     * for the current revision; a newer stylesheet is loaded beside the old one and takes its place once it
     * has arrived, so the page is never without one. A stylesheet that failed to load, or was still on its
     * way when the page was put away (such a load may never end), is asked for again then too.
     * @returns {() => void} Removes everything it added.
     */
    function start(doc) {
      // another copy of this module already runs here; an element of the page that only shares the id is not one
      if (doc.querySelector(`link#${LINK_ID}[rel="stylesheet"]`)) return () => {}
      const win = doc.defaultView
      const page = { id: Math.random().toString(36).slice(2, 10), seq: 0 }
      const href = `${new URL('custom-css/style.css', doc.baseURI).href}?p=${page.id}`
      const tally = createTally(win)
      /** The stylesheet the page is meant to use, and whether it has shown that it is applied. */
      let current = null
      let loaded = false
      let arriving = null
      let stalled = false
      let asking = false
      let touchAsked = -Infinity
      /** What the stylesheet in the page said when last read, and which settings the running features were started with. */
      let settings = readSettings(doc)
      let running = ''
      let stopFeatures = () => {}

      const onRevision = (latest) => {
        if (latest && latest !== settings.revision && loaded && arriving === null) link(`${href}&r=${encodeURIComponent(latest)}`)
      }
      /** Acts on what the stylesheet in the page says now, if that is not what is running. A start that failed is tried again the next time. */
      const sync = () => {
        settings = readSettings(doc)
        // a stylesheet that names its build is applied, whether or not its load event came
        if (settings.build !== '') loaded = true
        const wanted = JSON.stringify(settings)
        if (wanted === running) return
        try {
          stopFeatures()
          stopFeatures = () => {}
          running = ''
          stopFeatures = startFeatures(doc, settings, { page, tally, onRevision })
          running = wanted
        } catch (error) {
          tally.note('start', error)
        }
      }
      function link(address) {
        const next = doc.createElement('link')
        next.rel = 'stylesheet'
        next.href = address
        next.onload = () => {
          if (next === arriving) {
            if (current !== null) drop(current)
            current = next
            arriving = null
          }
          next.id = LINK_ID
          loaded = true
          sync()
        }
        next.onerror = () => {
          next.remove()
          if (current === next) current = null
          if (arriving === next) arriving = null
          tally.note('stylesheet', 'did not load')
        }
        if (current === null) {
          next.id = LINK_ID
          current = next
          loaded = false
        } else {
          arriving = next
        }
        doc.head.appendChild(next)
      }
      /** Takes a stylesheet that is still on its way out of the page; whatever it does later is not heard. */
      const drop = (node) => {
        node.onload = null
        node.onerror = null
        node.remove()
      }
      const ask = () => {
        if (doc.visibilityState !== 'visible') return
        if (stalled) {
          stalled = false
          if (arriving !== null) drop(arriving)
          arriving = null
          sync()
          if (current !== null && !loaded) {
            drop(current)
            current = null
          }
        }
        if (current === null) return void link(href)
        sync()
        // a first stylesheet still on its way says what to do when it lands
        if (!loaded || asking || arriving !== null) return
        asking = true
        win.fetch(href, { method: 'HEAD', cache: 'no-store' })
          .then((response) => {
            asking = false
            if (!response.ok) throw new Error(`HTTP ${response.status}`)
            onRevision(response.headers.get(REVISION_HEADER))
          })
          .catch((error) => {
            asking = false
            tally.note('revision', error)
          })
      }
      const onVisibility = () => {
        if (doc.visibilityState === 'visible') ask()
        else if (arriving !== null || (current !== null && !loaded)) stalled = true
      }
      /** A stylesheet from a Host half that is not this code's (an update still under way), or none at all: a touch asks again. */
      const onTouch = () => {
        sync()
        if (settings.build === BUILD || win.performance.now() - touchAsked < TOUCH_ASK_MS) return
        touchAsked = win.performance.now()
        ask()
      }

      link(href)
      doc.addEventListener('visibilitychange', onVisibility)
      win.addEventListener('pageshow', ask)
      win.addEventListener('online', ask)
      doc.addEventListener('pointerdown', onTouch, { capture: true, passive: true })
      return () => {
        doc.removeEventListener('visibilitychange', onVisibility)
        win.removeEventListener('pageshow', ask)
        win.removeEventListener('online', ask)
        doc.removeEventListener('pointerdown', onTouch, { capture: true })
        stopFeatures()
        arriving?.remove()
        current?.remove()
      }
    }

    return {
      inject: [],
      apply(ctx) {
        ctx.effect(() => (typeof document === 'undefined' ? () => {} : start(document)), 'custom-css: page')
      },
    }
  },
})

// ---- features/sidebar-split/client.js
/*
 * Browser half of dsh-sidebar-split. DSH's left sidebar stacks the global
 * panel list (Plugins, Cron tasks, every plugin's entry) above the
 * Workspaces browser, and the list never shrinks, so with many plugins the
 * workspaces get only what is left. This module turns the two into panes
 * split by a draggable sash, like VS Code's side bar: the list scrolls on its
 * own once it is shorter than its rows, the workspaces take the rest, and the
 * chosen split is kept per browser in localStorage.
 *
 * The sidebar offers no slot around these two blocks, so the module finds
 * them by structure: the `nav` panel list and the region area that follows
 * it inside the sidebar root. It only adds a sash element, data attributes
 * and one stylesheet, and removes all of them when it unloads. If a DSH
 * update renames those blocks, nothing is found and the sidebar stays as
 * shipped.
 *
 * Plain JavaScript in DSH's Client module format (no build step).
 */
feature("sidebarSplit", {
  id: 'dsh-sidebar-split',
  factory() {
    const STORAGE_KEY = 'dsh-sidebar-split'
    const STYLE_ID = 'dsh-sidebar-split-style'
    const SASH_CLASS = 'dsh-sidebar-split-sash'
    const ROOT_ATTR = 'data-sidebar-split'
    const CAPPED_ATTR = 'data-sidebar-split-capped'
    const HIDDEN_ATTR = 'data-sidebar-split-hidden'
    const DRAGGING_ATTR = 'data-sidebar-split-dragging'
    const RAIL_ATTR = 'data-sidebar-split-rail'
    const REGION_ATTR = 'data-sidebar-split-region'
    const LIST_VAR = '--dsh-sidebar-split-list'

    /** Share of the split area the panel list gets until the user picks one. */
    const DEFAULT_RATIO = 0.5
    /** Height the workspaces pane always keeps, in px. */
    const MIN_REGION = 96
    /** Dragging the list shorter than this hides it, in px. */
    const SNAP = 24
    /** Arrow-key step, in px. */
    const KEY_STEP = 24
    /** Pointer travel below which a press counts as a tap, in px. */
    const TAP_SLOP = 4
    /** Two taps closer than this toggle the list, in ms. */
    const DOUBLE_TAP_MS = 350

    const PANEL_LIST = 'nav[class*="_panelList"]'
    const REGION_CLASS = /(?:^|\s)[\w-]+_regionArea(?:\s|$)/
    const RAIL_CLASS = /(?:^|\s)[\w-]+_collapsed(?:\s|$)/

    const STYLE = `
[${ROOT_ATTR}] > nav {
  flex: 0 1 auto;
  min-height: 0;
  max-height: var(${LIST_VAR});
  margin-bottom: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
}
[${ROOT_ATTR}][${HIDDEN_ATTR}] > nav { visibility: hidden; }
.${SASH_CLASS} {
  position: relative;
  flex: none;
  height: 8px;
  margin-inline: calc(-1 * var(--dsh-sidebar-inline-padding, 8px));
  cursor: row-resize;
  touch-action: none;
  outline: none;
  -webkit-tap-highlight-color: transparent;
}
.${SASH_CLASS}::before {
  content: "";
  position: absolute;
  left: calc(var(--dsh-sidebar-inline-padding, 8px) + var(--dsh-sidebar-paint-inset, 3px));
  right: calc(var(--dsh-sidebar-inline-padding, 8px) + var(--dsh-sidebar-paint-inset, 3px));
  top: calc(50% - 0.5px);
  height: 1px;
  border-radius: 1px;
  background: transparent;
  transition: background-color 0.1s ease-out, top 0.1s ease-out, height 0.1s ease-out;
}
[${CAPPED_ATTR}] > .${SASH_CLASS}::before { background: var(--dsw-alias-border-l2); }
@media (hover: hover) {
  .${SASH_CLASS}:hover::before {
    transition-delay: 0.3s;
    top: calc(50% - 1px);
    height: 2px;
    background: var(--dsw-alias-state-business-primary);
  }
}
.${SASH_CLASS}[data-active]::before,
.${SASH_CLASS}:focus-visible::before {
  transition-delay: 0s;
  top: calc(50% - 1px);
  height: 2px;
  background: var(--dsw-alias-state-business-primary);
}
@media (pointer: coarse) {
  .${SASH_CLASS} { height: 20px; }
  .${SASH_CLASS}::after {
    content: "";
    position: absolute;
    left: 50%;
    top: 50%;
    width: 36px;
    height: 4px;
    margin: -2px 0 0 -18px;
    border-radius: 2px;
    background: var(--dsw-alias-border-l3);
  }
}
[${RAIL_ATTR}] > nav {
  flex: 0 1 auto;
  min-height: 0;
  margin-bottom: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: none;
}
[${RAIL_ATTR}] > nav::-webkit-scrollbar { display: none; }
[${RAIL_ATTR}][${CAPPED_ATTR}] > nav {
  -webkit-mask-image: linear-gradient(to bottom, #000 calc(100% - 20px), transparent);
  mask-image: linear-gradient(to bottom, #000 calc(100% - 20px), transparent);
}
[${RAIL_ATTR}] > [${REGION_ATTR}] { flex: none; }
[${RAIL_ATTR}] > .${SASH_CLASS} {
  height: 24px;
  margin-inline: 0;
  cursor: default;
  pointer-events: none;
}
[${RAIL_ATTR}] > .${SASH_CLASS}::before {
  left: calc(50% - 10px);
  right: auto;
  width: 20px;
  background: var(--dsw-alias-border-l2);
}
[${RAIL_ATTR}] > .${SASH_CLASS}::after { display: none; }
html[${DRAGGING_ATTR}], html[${DRAGGING_ATTR}] * {
  cursor: row-resize !important;
  user-select: none !important;
  -webkit-user-select: none !important;
}
`

    /**
     * Height the panel list may take.
     * @param {{ ratio: number | null, hidden: boolean }} state - The saved choice; a null ratio means the default.
     * @param {{ total: number, natural: number }} size - Height shared by list and workspaces, and the list's full content height.
     * @returns {number} The list's maximum height in px.
     */
    function listLimit(state, { total, natural }) {
      if (state.hidden) return 0
      const room = Math.max(0, total - MIN_REGION)
      const wanted = (state.ratio ?? DEFAULT_RATIO) * total
      return Math.max(0, Math.round(Math.min(wanted, natural, room)))
    }

    /**
     * The state a drag or key press to a list height leads to.
     * @param {number} height - Requested list height in px.
     * @param {{ total: number, natural: number }} size - As for listLimit.
     * @returns {{ ratio: number | null, hidden: boolean }} Hidden below SNAP; ratio 1 once every row fits, so the list keeps showing all of them.
     */
    function stateForHeight(height, { total, natural }) {
      if (height < SNAP) return { ratio: null, hidden: true }
      const room = Math.max(0, total - MIN_REGION)
      if (height >= natural && natural <= room) return { ratio: 1, hidden: false }
      if (total <= 0) return { ratio: null, hidden: false }
      return { ratio: Math.min(height, room) / total, hidden: false }
    }

    /** @param {string | null} text - Stored JSON. */
    function parseState(text) {
      try {
        const value = JSON.parse(text ?? 'null')
        const ratio = typeof value?.ratio === 'number' && value.ratio >= 0 && value.ratio <= 1 ? value.ratio : null
        return { ratio, hidden: value?.hidden === true }
      } catch {
        return { ratio: null, hidden: false }
      }
    }

    /** Find every sidebar's panel list and the workspaces region that follows it. */
    function findSidebars(doc) {
      const found = []
      for (const nav of doc.querySelectorAll(PANEL_LIST)) {
        const root = nav.parentElement
        if (root === null) continue
        const region = Array.from(root.children).find((el) => el !== nav && REGION_CLASS.test(el.className))
        if (region !== undefined) found.push({ root, nav, region })
      }
      return found
    }

    /**
     * One sidebar's split: the sash, its pointer and keyboard handling, and
     * the list height it writes onto the sidebar root.
     */
    function createSplit(doc, parts, store) {
      let { root, nav, region } = parts
      const sash = doc.createElement('div')
      sash.className = SASH_CLASS
      sash.setAttribute('role', 'separator')
      sash.setAttribute('aria-orientation', 'horizontal')
      sash.setAttribute('aria-valuemin', '0')
      sash.setAttribute('aria-valuemax', '100')
      sash.tabIndex = 0

      let drag = null
      let lastTap = 0
      let frame = 0
      const win = doc.defaultView

      const size = () => ({
        total: nav.getBoundingClientRect().height + region.getBoundingClientRect().height,
        natural: nav.scrollHeight,
      })

      const place = () => {
        if (sash.previousElementSibling !== nav || sash.nextElementSibling !== region) root.insertBefore(sash, region)
        if (!region.hasAttribute(REGION_ATTR)) region.setAttribute(REGION_ATTR, '')
      }

      /** The icon rail: a fixed divider, panel icons scroll above it, workspace icons keep their height below. */
      const showRail = () => {
        if (root.hasAttribute(ROOT_ATTR)) {
          root.removeAttribute(ROOT_ATTR)
          root.removeAttribute(HIDDEN_ATTR)
          root.style.removeProperty(LIST_VAR)
        }
        if (!root.hasAttribute(RAIL_ATTR)) root.setAttribute(RAIL_ATTR, '')
        place()
        sash.tabIndex = -1
        sash.setAttribute('aria-hidden', 'true')
        root.toggleAttribute(CAPPED_ATTR, nav.scrollTop + nav.clientHeight < nav.scrollHeight - 1)
      }

      const show = (state) => {
        if (RAIL_CLASS.test(root.className)) {
          showRail()
          return
        }
        if (root.hasAttribute(RAIL_ATTR)) root.removeAttribute(RAIL_ATTR)
        if (!root.hasAttribute(ROOT_ATTR)) root.setAttribute(ROOT_ATTR, '')
        place()
        sash.tabIndex = 0
        sash.removeAttribute('aria-hidden')
        if (nav.id === '') nav.id = `dsh-sidebar-split-list-${Math.random().toString(36).slice(2, 8)}`
        sash.setAttribute('aria-controls', nav.id)
        sash.setAttribute('aria-labelledby', nav.id)
        const geometry = size()
        const limit = listLimit(state, geometry)
        const value = `${limit}px`
        if (root.style.getPropertyValue(LIST_VAR) !== value) root.style.setProperty(LIST_VAR, value)
        root.toggleAttribute(CAPPED_ATTR, limit < geometry.natural - 1)
        root.toggleAttribute(HIDDEN_ATTR, state.hidden)
        const percent = geometry.total > 0 ? Math.round((limit / geometry.total) * 100) : 0
        sash.setAttribute('aria-valuenow', String(percent))
      }

      const sync = () => {
        frame = 0
        if (drag === null) show(store.get())
      }
      const schedule = () => {
        if (frame === 0) frame = win.requestAnimationFrame(sync)
      }

      const preview = (height) => {
        const state = stateForHeight(height, size())
        show(state)
        return state
      }

      const onPointerDown = (event) => {
        if (event.button !== 0 || root.hasAttribute(RAIL_ATTR)) return
        event.preventDefault()
        sash.setPointerCapture(event.pointerId)
        drag = { id: event.pointerId, y: event.clientY, height: nav.getBoundingClientRect().height, moved: false, state: store.get() }
        sash.setAttribute('data-active', '')
        doc.documentElement.setAttribute(DRAGGING_ATTR, '')
      }
      const onPointerMove = (event) => {
        if (drag === null || event.pointerId !== drag.id) return
        const dy = event.clientY - drag.y
        if (!drag.moved && Math.abs(dy) < TAP_SLOP) return
        drag.moved = true
        drag.state = preview(drag.height + dy)
      }
      const finish = (event) => {
        if (drag === null || event.pointerId !== drag.id) return
        const { moved, state } = drag
        drag = null
        sash.removeAttribute('data-active')
        doc.documentElement.removeAttribute(DRAGGING_ATTR)
        if (moved) {
          lastTap = 0
          store.set(state)
          return
        }
        if (event.type !== 'pointerup') return
        const now = event.timeStamp
        if (now - lastTap < DOUBLE_TAP_MS) {
          lastTap = 0
          store.toggle()
        } else {
          lastTap = now
        }
      }
      const onKeyDown = (event) => {
        if (root.hasAttribute(RAIL_ATTR)) return
        const height = listLimit(store.get(), size())
        let state
        if (event.key === 'ArrowUp') state = stateForHeight(height - KEY_STEP, size())
        else if (event.key === 'ArrowDown') state = stateForHeight(Math.max(height, SNAP) + KEY_STEP, size())
        else if (event.key === 'Home') state = { ...store.get(), hidden: true }
        else if (event.key === 'End') state = { ratio: 1, hidden: false }
        else if (event.key === 'Enter' || event.key === ' ') {
          event.preventDefault()
          store.toggle()
          return
        } else return
        event.preventDefault()
        store.set(state)
      }

      sash.addEventListener('pointerdown', onPointerDown)
      sash.addEventListener('pointermove', onPointerMove)
      sash.addEventListener('pointerup', finish)
      sash.addEventListener('pointercancel', finish)
      sash.addEventListener('lostpointercapture', finish)
      sash.addEventListener('keydown', onKeyDown)

      const resize = new win.ResizeObserver(schedule)
      const mutations = new win.MutationObserver(schedule)
      let scrolled = null
      const observe = () => {
        scrolled?.removeEventListener('scroll', schedule)
        scrolled = nav
        nav.addEventListener('scroll', schedule, { passive: true })
        resize.disconnect()
        mutations.disconnect()
        resize.observe(root)
        resize.observe(region)
        mutations.observe(root, { attributes: true, attributeFilter: ['class'] })
        mutations.observe(root, { childList: true })
        mutations.observe(nav, { childList: true, subtree: true })
      }
      observe()

      function detach() {
        sash.remove()
        region.removeAttribute(REGION_ATTR)
        root.removeAttribute(RAIL_ATTR)
        root.removeAttribute(ROOT_ATTR)
        root.removeAttribute(CAPPED_ATTR)
        root.removeAttribute(HIDDEN_ATTR)
        root.style.removeProperty(LIST_VAR)
      }

      return {
        root,
        /** Follow a re-rendered list or region inside the same root. */
        adopt(next) {
          if (next.nav === nav && next.region === region) return
          if (next.region !== region) region.removeAttribute(REGION_ATTR)
          nav = next.nav
          region = next.region
          observe()
          schedule()
        },
        connected: () => root.isConnected,
        refresh: schedule,
        apply: () => {
          if (drag === null) show(store.get())
        },
        dispose() {
          if (frame !== 0) win.cancelAnimationFrame(frame)
          resize.disconnect()
          mutations.disconnect()
          scrolled?.removeEventListener('scroll', schedule)
          if (drag !== null) doc.documentElement.removeAttribute(DRAGGING_ATTR)
          detach()
          if (nav.id.startsWith('dsh-sidebar-split-list-')) nav.removeAttribute('id')
        },
      }
    }

    /** The saved split, shared by every sidebar in the page and by other tabs. */
    function createStore(win, onChange) {
      const storage = (() => {
        try {
          return win.localStorage
        } catch {
          return null
        }
      })()
      let state = parseState(storage?.getItem(STORAGE_KEY) ?? null)
      const set = (next) => {
        state = { ratio: next.ratio, hidden: next.hidden }
        try {
          storage?.setItem(STORAGE_KEY, JSON.stringify(state))
        } catch {
          // Private mode or a full quota: the split still applies until reload.
        }
        onChange()
      }
      return {
        get: () => state,
        set,
        toggle: () => set({ ratio: state.ratio, hidden: !state.hidden }),
        reload: () => {
          state = parseState(storage?.getItem(STORAGE_KEY) ?? null)
          onChange()
        },
      }
    }

    function start(doc) {
      const win = doc.defaultView
      const splits = new Map()
      const store = createStore(win, () => {
        for (const split of splits.values()) split.apply()
      })

      const style = doc.createElement('style')
      style.id = STYLE_ID
      style.textContent = STYLE
      doc.head.appendChild(style)

      let frame = 0
      const scan = () => {
        frame = 0
        const seen = new Set()
        for (const parts of findSidebars(doc)) {
          seen.add(parts.root)
          const split = splits.get(parts.root)
          if (split === undefined) splits.set(parts.root, createSplit(doc, parts, store))
          else split.adopt(parts)
          splits.get(parts.root).refresh()
        }
        for (const [root, split] of splits) {
          if (!seen.has(root) || !split.connected()) {
            split.dispose()
            splits.delete(root)
          }
        }
      }
      const schedule = () => {
        if (frame === 0) frame = win.requestAnimationFrame(scan)
      }
      const touchesSidebar = (node) =>
        node.nodeType === 1 && (node.matches(PANEL_LIST) || node.querySelector(PANEL_LIST) !== null || REGION_CLASS.test(node.className))
      const page = new win.MutationObserver((records) => {
        for (const record of records) {
          for (const node of record.addedNodes) if (touchesSidebar(node)) return schedule()
          for (const node of record.removedNodes) if (touchesSidebar(node)) return schedule()
        }
      })
      page.observe(doc.body, { childList: true, subtree: true })

      const onStorage = (event) => {
        if (event.key === STORAGE_KEY || event.key === null) store.reload()
      }
      win.addEventListener('storage', onStorage)
      scan()

      return () => {
        if (frame !== 0) win.cancelAnimationFrame(frame)
        page.disconnect()
        win.removeEventListener('storage', onStorage)
        for (const split of splits.values()) split.dispose()
        splits.clear()
        style.remove()
      }
    }

    return {
      inject: [],
      apply(ctx) {
        if (typeof document === 'undefined') return
        ctx.effect(() => start(document), 'sidebar-split: panes')
      },
      listLimit,
      stateForHeight,
      parseState,
    }
  },
})

// ---- features/file-download/client.js
/*
 * Browser half of dsh-file-download. DSH 0.2.2 can download a Session file
 * only from its context menu, which opens on right-click or the keyboard, so
 * a phone has no way to reach it. This module adds a visible Download button
 * to the document preview: in its header, in the empty state of a file the
 * preview cannot show (a zip, an installer), and on the card of a delivered
 * (presented) file.
 *
 * The download itself is DSH's own `fileActions.save(source, 'download')`,
 * the same operation the context menu runs. The bytes come from the
 * authorized `workspaceFiles.readBytes` Remote in bounded windows, so a file
 * above the Host's complete-file cap still downloads.
 *
 * Plain JavaScript in DSH's Client module format (no build step).
 */
feature("fileDownload", {
  id: 'dsh-file-download',
  factory: (require) => {
    const module = { exports: {} }
    const exports = module.exports
    Object.defineProperty(exports, Symbol.toStringTag, { value: 'Module' })

    const React = require('react')
    const { Button, Tooltip, IconDownloadOutlineRegular } = require('@deepseek-ai/dsh-client-ui-primitives')

    const NS = 'fileDownload'
    const STYLE_ID = 'dsh-file-download-style'
    /** First window size: the Host's default per-window cap (`maxBytes`). */
    const WINDOW_BYTES = 2 * 1024 * 1024

    const en = {
      download: 'Download',
      downloading: 'Preparing download…',
      started: 'Download started',
      failed: 'Could not download the file. Try again.',
    }
    const zh = {
      download: '下载',
      downloading: '正在准备下载…',
      started: '已开始下载',
      failed: '无法下载文件，请重试',
    }

    /** Media types for the suffixes people most often download; the rest go as bytes. */
    const MEDIA_TYPES = {
      pdf: 'application/pdf', zip: 'application/zip', json: 'application/json', txt: 'text/plain',
      md: 'text/markdown', csv: 'text/csv', html: 'text/html', png: 'image/png', jpg: 'image/jpeg',
      jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp', svg: 'image/svg+xml', mp3: 'audio/mpeg',
      mp4: 'video/mp4', mov: 'video/quicktime', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
      ipa: 'application/octet-stream', apk: 'application/vnd.android.package-archive',
    }

    /**
     * The file name a path ends in, for POSIX and Windows paths alike.
     * @param path - absolute path in the file's execution environment.
     * @returns the last path segment.
     */
    function basenameOf(path) {
      const trimmed = path.replace(/[\\/]+$/u, '')
      return trimmed.slice(Math.max(trimmed.lastIndexOf('/'), trimmed.lastIndexOf('\\')) + 1)
    }

    /**
     * Media type for a file name, or '' when unknown (the download keeps its name then).
     * @param name - file name.
     * @returns the MIME type or ''.
     */
    function mediaTypeOf(name) {
      const dot = name.lastIndexOf('.')
      return dot <= 0 ? '' : MEDIA_TYPES[name.slice(dot + 1).toLowerCase()] ?? ''
    }

    /**
     * The original's authenticated URL (DSH's `/api/file` route), which names
     * the source; the bytes themselves come from `read`.
     * @param path - absolute file path.
     * @returns an absolute URL beside the app.
     */
    function fileUrl(path) {
      const base = typeof document === 'undefined' ? 'http://localhost/' : document.baseURI
      return new URL(`api/file?path=${encodeURIComponent(path)}`, base).href
    }

    /**
     * A signal that aborts when either input does.
     * @param first - one signal.
     * @param second - the other.
     * @returns the combined signal.
     */
    function eitherSignal(first, second) {
      const controller = new AbortController()
      for (const signal of [first, second]) {
        if (signal.aborted) controller.abort(signal.reason)
        else signal.addEventListener('abort', () => { controller.abort(signal.reason) }, { once: true })
      }
      return controller.signal
    }

    /**
     * Read a whole file through bounded `readBytes` windows. A Host with a
     * tighter window cap answers `workspace-file/too-large` with its limit,
     * and the walk continues at that size.
     * @param readBytes - `remote.workspaceFiles.readBytes`.
     * @param sessionId - Session whose filesystem authorizes the read.
     * @param path - absolute file path.
     * @param mediaType - type recorded on the Blob.
     * @param signal - cancels the walk.
     * @returns the file's bytes.
     */
    async function readWhole(readBytes, sessionId, path, mediaType, signal) {
      const parts = []
      let offset = 0
      let length = WINDOW_BYTES
      for (;;) {
        signal.throwIfAborted()
        const result = await readBytes(sessionId, path, { range: { offset, length } }, signal)
        if (!result.ok) {
          const limit = result.error?.code === 'workspace-file/too-large' ? result.error.details?.limit : undefined
          if (Number.isSafeInteger(limit) && limit > 0 && limit < length) {
            length = limit
            continue
          }
          throw new Error(`File read failed: ${result.error?.code ?? 'unknown'}`)
        }
        const data = result.value.data
        if (data.byteLength > 0) parts.push(data)
        offset += data.byteLength
        if (result.value.eof || data.byteLength === 0) break
      }
      return new Blob(parts, { type: mediaType })
    }

    /**
     * Session id a delivery card's action URL names (the card's slot passes only that URL).
     * @param actionUrl - the card's `present.open` route with its query.
     * @returns the Session id, or '' when the URL doesn't carry one.
     */
    function sessionIdOf(actionUrl) {
      try { return new URL(actionUrl, 'http://localhost/').searchParams.get('sessionId') ?? '' } catch { return '' }
    }

    /**
     * The absolute path a delivery card stands for. The card's action slot is not
     * given the file, but the card's own preview button carries it as its title.
     * @param element - any element inside the card.
     * @returns the path, or '' when the card has no path to read.
     */
    function cardPathOf(element) {
      const title = element?.closest?.('[data-presented-file]')?.querySelector('button[title]')?.getAttribute('title')
      if (typeof title !== 'string') return ''
      return title.startsWith('/') || /^[A-Za-z]:[\\/]/u.test(title) ? title : ''
    }

    /** Header button sized like the preview's other 24px icon controls. */
    const CSS = `
.dsh-fd-icon { display: inline-flex; align-items: center; justify-content: center; width: 24px; height: 24px;
  padding: 0; border: 0; border-radius: 6px; background: transparent; color: inherit; cursor: pointer; }
.dsh-fd-icon:hover:not(:disabled) { background: var(--dsw-alias-button-ghost-bg-hover, rgba(127, 127, 127, 0.14)); }
.dsh-fd-icon:disabled { opacity: 0.5; cursor: default; }
.dsh-fd-icon svg { width: 16px; height: 16px; }
.dsh-fd-card { display: inline-flex; align-items: center; gap: 4px; height: 28px; padding: 0 10px; border-radius: 8px;
  border: 0.5px solid var(--dsw-alias-border-l1, rgba(127, 127, 127, 0.3)); background: transparent; color: inherit;
  font: inherit; font-size: 12px; line-height: 20px; cursor: pointer; white-space: nowrap; }
.dsh-fd-card:hover:not(:disabled) { background: var(--dsw-alias-button-ghost-bg-hover, rgba(127, 127, 127, 0.14)); }
.dsh-fd-card:disabled { opacity: 0.5; cursor: default; }
.dsh-fd-card svg { width: 14px; height: 14px; }
`

    function installStyle() {
      if (typeof document === 'undefined' || document.getElementById(STYLE_ID) !== null) return () => {}
      const style = document.createElement('style')
      style.id = STYLE_ID
      style.textContent = CSS
      document.head.append(style)
      return () => { style.remove() }
    }

    /**
     * Shared gesture state of one control: one download at a time, cancelled on unmount.
     * @param props - slot props with the injected `start`.
     * @returns busy flag and the click handler.
     */
    function useDownload(props) {
      const [busy, setBusy] = React.useState(false)
      const running = React.useRef(null)
      React.useEffect(() => () => { running.current?.abort() }, [])
      const onClick = React.useCallback(() => {
        if (running.current !== null) return
        const controller = new AbortController()
        running.current = controller
        setBusy(true)
        void props.start(props.absolutePath, controller.signal).finally(() => {
          if (running.current === controller) running.current = null
          if (!controller.signal.aborted) setBusy(false)
        })
      }, [props.absolutePath, props.start])
      return { busy, onClick }
    }

    /** Icon button in the document header. */
    function HeaderDownload(props) {
      const { busy, onClick } = useDownload(props)
      if (typeof props.absolutePath !== 'string') return null
      const label = busy ? props.t('downloading') : props.t('download')
      return React.createElement(Tooltip, { portal: true, label, side: 'bottom', delayMs: 500 },
        React.createElement('button', {
          type: 'button', className: 'dsh-fd-icon', disabled: busy, 'aria-label': label,
          'data-file-download': 'header', onClick,
        }, React.createElement(IconDownloadOutlineRegular, null)))
    }

    /** Labelled button in the empty state of a file the preview cannot show. */
    function EmptyDownload(props) {
      const { busy, onClick } = useDownload(props)
      if (typeof props.absolutePath !== 'string') return null
      return React.createElement(Button, {
        variant: 'outline', disabled: busy, 'data-file-download': 'empty', onClick,
        icon: React.createElement(IconDownloadOutlineRegular, null),
      }, busy ? props.t('downloading') : props.t('download'))
    }

    /**
     * Button on a delivered file's card. It reads the file's path from the card at
     * click time and downloads it, whatever the file type.
     * @param props - the card slot's props (`actionUrl`) and the injected `start`.
     */
    function CardDownload(props) {
      const anchor = React.useRef(null)
      const [busy, setBusy] = React.useState(false)
      const running = React.useRef(null)
      React.useEffect(() => () => { running.current?.abort() }, [])
      const onClick = React.useCallback(() => {
        if (running.current !== null) return
        const path = cardPathOf(anchor.current)
        if (path === '') return
        const controller = new AbortController()
        running.current = controller
        setBusy(true)
        void props.start(sessionIdOf(props.actionUrl), path, controller.signal).finally(() => {
          if (running.current === controller) running.current = null
          if (!controller.signal.aborted) setBusy(false)
        })
      }, [props.actionUrl, props.start])
      const label = busy ? props.t('downloading') : props.t('download')
      return React.createElement('button', {
        ref: anchor, type: 'button', className: 'dsh-fd-card', disabled: busy, 'aria-label': label,
        'data-file-download': 'card', onClick,
      }, React.createElement(IconDownloadOutlineRegular, null), props.t('download'))
    }

    const inject = ['slots', 'locale', 'fileActions', 'contextMenus', 'remote', 'remote.workspaceFiles']

    /**
     * Register the dictionaries and both Download controls for the plugin's lifetime.
     * @param ctx - client root context.
     */
    function apply(ctx) {
      ctx.effect(installStyle, 'file-download: style')
      ctx.effect(() => ctx.locale.register(NS, { en, zh }), 'file-download: dictionaries')
      const t = ctx.locale.bind(NS)
      const download = async (sessionId, absolutePath, signal) => {
        const name = basenameOf(absolutePath)
        const mediaType = mediaTypeOf(name)
        try {
          const result = await ctx.fileActions.save({
            url: fileUrl(absolutePath), name, mediaType,
            read: (readSignal) => readWhole(
              (...args) => ctx.remote.workspaceFiles.readBytes(...args), sessionId, absolutePath, mediaType,
              eitherSignal(signal, readSignal)),
          }, 'download')
          if (result.status !== 'cancelled') ctx.contextMenus.notify(t('started'), true)
        } catch (error) {
          if (signal.aborted) return
          console.warn('dsh-file-download:', error)
          ctx.contextMenus.notify(t('failed'), false)
        }
      }
      const injected = (sessionId) => ({ start: (absolutePath, signal) => download(sessionId, absolutePath, signal) })
      for (const [name, component] of [
        ['sidebar.right.tab.document.actions', HeaderDownload],
        ['sidebar.right.tab.document.unpreviewable', EmptyDownload],
      ]) {
        ctx.effect(() => ctx.slots.inject(name, () => ctx.slots.register({
          name, id: 'file-download', order: 100, locale: NS, inject: injected,
        }, component)), `file-download: ${name}`)
      }
      ctx.effect(() => ctx.slots.inject('deliverables.file.actions', () => ctx.slots.register({
        name: 'deliverables.file.actions', id: 'file-download', order: 100, locale: NS,
        inject: () => ({ start: download }),
      }, CardDownload)), 'file-download: deliverables.file.actions')
    }

    exports.apply = apply
    exports.inject = inject
    exports.basenameOf = basenameOf
    exports.sessionIdOf = sessionIdOf
    exports.cardPathOf = cardPathOf
    exports.mediaTypeOf = mediaTypeOf
    exports.readWhole = readWhole
    return module.exports
  },
})

// ---- features/subagent-model/client.js
/*
 * Browser half of dsh-subagent-model: a read-only model label in the composer
 * of subagent sessions.
 *
 * The shipped model picker owns the composer's one model seat and renders
 * nothing for subagent sessions, because their model cannot be switched. The
 * label goes into the neighbouring list slot, right before that seat, so the
 * shipped package stays untouched. The model and effort come from the same
 * per-session directory the picker reads (the session's recorded selection
 * resolved against the model catalog); the label never writes to it.
 *
 * Plain JavaScript in DSH's Client module format (no build step). React comes
 * from the page's module table. Styles use only the host theme tokens.
 */
feature("subagentModel", {
  id: 'dsh-subagent-model',
  factory(require) {
    const React = require('react')
    const h = React.createElement
    const { useSyncExternalStore } = React

    const NS = 'dsh-subagent-model'
    const STYLE_ID = 'dsh-subagent-model'
    const SLOT = 'conversation.input.right'

    const en = {
      aria: 'Model: {model}',
      ariaEffort: 'Model: {model}, reasoning {effort}',
    }
    const zh = {
      aria: '模型：{model}',
      ariaEffort: '模型：{model}，推理强度 {effort}',
    }

    // Same box as the shipped model seat's trigger, minus the hover and the chevron.
    const CSS = `
.dsm-label{box-sizing:border-box;display:flex;align-items:center;gap:4px;min-width:0;max-width:360px;height:28px;padding:0 8px;color:var(--dsw-alias-label-secondary);font-size:13px;font-weight:400;line-height:20px;cursor:default;user-select:none;-webkit-user-select:none}
.dsm-model{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.dsm-effort{min-width:0;flex-shrink:1000;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--dsw-alias-label-caption)}
`

    /**
     * The model and effort names a directory snapshot stands for, resolved
     * the way the shipped seat does it (catalog name, effort level name,
     * the model's default effort when none is recorded). A model the catalog
     * does not list shows its id. Nothing until a selection is known.
     */
    function describe(snapshot) {
      const current = snapshot?.current
      if (current === null || current === undefined) return undefined
      const group = snapshot.groups?.find(item => item.id === current.provider)
      const model = group?.models?.find(item => item.id === current.model)
      const reasoning = model?.reasoning
      const effort = current.reasoningEffort ?? reasoning?.defaultEffort
      const effortName = effort === undefined
        ? undefined
        : reasoning?.efforts?.find(level => level.id === effort)?.name ?? effort
      return { model: model?.name ?? current.model, effort: effortName }
    }

    function Label({ t, store }) {
      const snapshot = useSyncExternalStore(fn => store.subscribe(fn), () => store.getSnapshot())
      const shown = describe(snapshot)
      if (shown === undefined) return null
      const title = shown.effort === undefined ? shown.model : `${shown.model} · ${shown.effort}`
      const aria = shown.effort === undefined
        ? t('aria', { model: shown.model })
        : t('ariaEffort', { model: shown.model, effort: shown.effort })
      return h('span', { className: 'dsm-label', title, 'aria-label': aria, 'data-provider-id': snapshot.current.provider, 'data-model-id': snapshot.current.model },
        h('span', { className: 'dsm-model' }, shown.model),
        shown.effort === undefined ? null : h('span', { className: 'dsm-effort' }, shown.effort))
    }

    /** Only subagent sessions get a label; the shipped seat covers the rest. */
    function SubagentModel({ t, sessionId, sessions, modelDirectories }) {
      if (sessionId === undefined || sessions.subagentAddress(sessionId) === undefined) return null
      let directory
      try {
        directory = modelDirectories.directoryFor(sessionId)
      } catch {
        return null
      }
      return h(Label, { t, store: directory.store })
    }

    return {
      inject: ['slots', 'locale', 'sessions', 'modelDirectories'],
      apply(ctx) {
        ctx.effect(() => {
          const disposers = [ctx.locale.register(NS, 'en', en), ctx.locale.register(NS, 'zh', zh)]
          return () => { for (const dispose of disposers) dispose() }
        }, 'subagent-model: dictionaries')
        const t = ctx.locale.bind(NS)

        ctx.effect(() => {
          if (typeof document === 'undefined' || document.getElementById(STYLE_ID)) return () => {}
          const tag = document.createElement('style')
          tag.id = STYLE_ID
          tag.dataset.plugin = NS
          tag.textContent = CSS
          document.head.appendChild(tag)
          return () => tag.remove()
        }, 'subagent-model: styles')

        ctx.slots.inject(SLOT, () => ctx.slots.register({
          name: SLOT,
          id: 'subagent-model',
          order: 1000,
          locale: NS,
          inject: sessionId => ({ t, sessionId, sessions: ctx.sessions, modelDirectories: ctx.modelDirectories }),
        }, SubagentModel))
      },
    }
  },
})

// ---- src/runtime.js
/**
 * Browser runtime of @soffits/dsh-web-tweaks, inlined into client.js by scripts/build-client.js.
 *
 * DSH hands a plugin's browser half no row config, so the page asks the Host which features are on
 * (`web-tweaks/features.json`) and runs each one that is as a child plugin with its own `inject`.
 * It asks again whenever the page comes to the front, so a changed switch needs no reload; a
 * failed ask is retried with a growing delay (DSH restarting, the network away). A feature's module
 * is created only when it is first turned on.
 *
 * @param {object} ctx - this plugin's browser context.
 * @param {Map<string, (require: Function) => object>} factories - feature key to module factory.
 * @param {Function} require - the page's module require.
 */
function runFeatures(ctx, factories, require) {
  const doc = typeof document === 'undefined' ? undefined : document
  const win = doc?.defaultView
  if (doc === undefined || win === undefined || typeof win.fetch !== 'function') return
  const FIRST_RETRY_MS = 1000
  const LAST_RETRY_MS = 60000
  const modules = new Map()
  const running = new Map()
  let stopped = false
  let timer = 0
  let delay = FIRST_RETRY_MS
  let asking = false

  const reconcile = (on) => {
    for (const [key, factory] of factories) {
      const fiber = running.get(key)
      if (on[key] === true && fiber === undefined) {
        if (!modules.has(key)) modules.set(key, factory(require))
        running.set(key, ctx.plugin(modules.get(key)))
      } else if (on[key] !== true && fiber !== undefined) {
        running.delete(key)
        fiber.dispose()
      }
    }
  }

  const ask = async () => {
    if (stopped || asking) return
    asking = true
    win.clearTimeout(timer)
    try {
      const res = await win.fetch(new URL('web-tweaks/features.json', doc.baseURI).href, { cache: 'no-store' })
      if (!res.ok) throw new Error(`features: HTTP ${res.status}`)
      const on = await res.json()
      if (stopped) return
      delay = FIRST_RETRY_MS
      reconcile(on)
    } catch (error) {
      if (stopped) return
      console.warn('web-tweaks:', error)
      timer = win.setTimeout(ask, delay)
      delay = Math.min(delay * 2, LAST_RETRY_MS)
    } finally {
      asking = false
    }
  }

  const onVisibility = () => { if (doc.visibilityState === 'visible') ask() }

  ctx.effect(() => {
    ask()
    doc.addEventListener('visibilitychange', onVisibility)
    win.addEventListener('online', ask)
    return () => {
      stopped = true
      win.clearTimeout(timer)
      doc.removeEventListener('visibilitychange', onVisibility)
      win.removeEventListener('online', ask)
      for (const fiber of running.values()) fiber.dispose()
      running.clear()
    }
  }, 'web-tweaks: features')
}

    return {
      inject: [],
      apply(ctx) { runFeatures(ctx, factories, require) },
    }
  },
})
